INSERT OR IGNORE INTO content_sections (name, data) VALUES ('services', '[{"icon":"ShieldCheck","title":"Audit de sécurité & conformité","text":"Cartographie de vos risques et mise en conformité avec les référentiels internationaux.","points":["ISO 27001 & NIS2","RGPD & protection des données","Plan d''action priorisé"]},{"icon":"Bug","title":"Tests d''intrusion (Pentest)","text":"Simulation d''attaques contrôlées sur vos infrastructures, applications et réseaux.","points":["Pentest interne & externe","Tests d''applications web","Rapport détaillé et remédiation"]},{"icon":"ScrollText","title":"Gouvernance & gestion des risques","text":"Structuration de votre gouvernance cybersécurité et pilotage des risques.","points":["RSSI à la demande","Politiques & procédures","Tableaux de bord de risques"]},{"icon":"GraduationCap","title":"Formation & sensibilisation","text":"Développez une culture sécurité durable au sein de votre organisation.","points":["Sensibilisation des employés","Certifications (CEH, ISO)","Phishing simulé"]},{"icon":"Siren","title":"Réponse aux incidents & SOC","text":"Détection, analyse et résolution rapide des incidents de sécurité.","points":["Réponse 24/7","Analyse forensique","Supervision sécurité (SOC)"]},{"icon":"CloudCog","title":"Sécurité cloud & DevSecOps","text":"Sécurisation de vos environnements cloud et intégration de la sécurité au cycle DevOps.","points":["Azure, AWS & GCP","CI/CD sécurisé","Sécurité des conteneurs"]}]');
