INSERT OR IGNORE INTO content_sections (name, data) VALUES ('why_choose', '[{"icon":"Users","title":"Équipe professionnelle certifiée","text":"Des experts certifiés (CISSP, CEH, ISO 27001 Lead Auditor) qui livrent des résultats mesurables et concrets."},{"icon":"MessageCircle","title":"Support dédié 24/7","text":"Une assistance réactive et un interlocuteur unique pour répondre à vos besoins de sécurité en continu."},{"icon":"Scale","title":"Approche conforme & éthique","text":"Nos interventions respectent strictement les réglementations nationales et les bonnes pratiques internationales."}]');
INSERT OR IGNORE INTO content_sections (name, data) VALUES ('process', '[{"icon":"FileSearch","title":"Évaluez votre exposition","text":"Analysez votre contexte, recueillez vos besoins et identifiez vos points faibles.","points":["Consultation initiale","Collecte des exigences"]},{"icon":"LineChart","title":"Planifiez la stratégie","text":"Élaborez des stratégies sur mesure pour une croissance durable de votre sécurité.","points":["Analyse de l''existant","Feuille de route personnalisée"]},{"icon":"Rocket","title":"Déployez & optimisez","text":"Implémentez les solutions et améliorez en continu vos performances sécurité.","points":["Déploiement des mesures","Suivi & optimisation continue"]}]');
