INSERT OR IGNORE INTO content_sections (name, data) VALUES ('testimonials', '[{"logo":"Nabhan","quote":"APSI-CG a transformé notre stratégie de sécurité. Leur audit a identifié des failles critiques que nous ignorions, et leurs recommandations ont réduit nos coûts et renforcé notre résilience.","name":"Tomas Addision","role":"CEO — Banque Nationale","img":"https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?auto=format&fit=crop&w=200&q=80","rating":5},{"logo":"Congo Telecom","quote":"Nous recommandons vivement APSI-CG pour tout besoin de cybersécurité. Leur approche professionnelle, leur réflexion stratégique et leurs solutions concrètes nous ont convaincus.","name":"Jakulin Farna","role":"MD — Congo Telecom","img":"https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=200&q=80","rating":5},{"logo":"Logitek","quote":"La formation dispensée par APSI-CG a changé la culture sécurité de nos équipes. Les résultats sont mesurables : moins d''incidents, plus de vigilance, un vrai professionnalisme.","name":"Donald Shaver","role":"CFO — Logitek","img":"https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=200&q=80","rating":5}]');
INSERT OR IGNORE INTO content_sections (name, data) VALUES ('faqs', '[{"q":"Faut-il des connaissances techniques pour faire auditer son entreprise ?","a":"Non. Nos experts vous accompagnent pas à pas. Nous commençons toujours par comprendre votre activité et vos objectifs, puis nous traduisons les aspects techniques en recommandations claires et actionnables pour vos équipes dirigeantes."},{"q":"Proposez-vous des solutions de sécurité personnalisées ?","a":"Absolument. Chaque organisation est unique : nous construisons des feuilles de route sur mesure après une évaluation approfondie de votre contexte, de vos risques et de votre budget. Aucune solution standardisée imposée."},{"q":"Quels types de services de sécurité proposez-vous ?","a":"Audit et conformité (ISO 27001, NIS2, RGPD), tests d''intrusion, gouvernance et gestion des risques, formation et sensibilisation, réponse aux incidents, supervision SOC et sécurité cloud/DevSecOps."},{"q":"Quelle est la durée typique d''une mission de consulting ?","a":"Une mission d''audit prend généralement de 2 à 6 semaines selon la taille de l''organisation. Les accompagnements en gouvernance s''étendent sur 3 à 12 mois. Nous établissons toujours un calendrier clair dès le départ."},{"q":"Comment devenir membre de l''association ?","a":"Trois étapes simples : remplissez le formulaire d''adhésion en ligne, réglez votre cotisation annuelle, puis rejoignez notre communauté de professionnels. Vous accéderez à nos formations, événements et réseaux d''expertise."},{"q":"Intervenez-vous uniquement à Brazzaville ?","a":"Non. Nos équipes interviennent dans tout le Congo et en Afrique centrale. Nos services de supervision (SOC) et de formation en ligne sont accessibles partout où vous avez une connexion internet."}]');
INSERT OR IGNORE INTO content_sections (name, data) VALUES ('pricing', '[{"name":"Membre Individuel","price":"50 000","period":"FCFA / an","desc":"Pour les professionnels souhaitant adhérer à la communauté.","features":[{"text":"Adhésion à l''association","included":true},{"text":"Accès aux événements & conférences","included":true},{"text":"Webinaires mensuels","included":true},{"text":"Réductions sur les formations","included":true},{"text":"Accès au réseau d''experts","included":false},{"text":"Support sécurité prioritaire","included":false}],"featured":false},{"name":"Membre Organisation","price":"250 000","period":"FCFA / an","desc":"Pour les entreprises et organisations de toutes tailles.","features":[{"text":"Jusqu''à 5 membres inclus","included":true},{"text":"Tous les avantages individuels","included":true},{"text":"2 formations annuelles offertes","included":true},{"text":"Accès au réseau d''experts","included":true},{"text":"Alerte menaces & veille cyber","included":true},{"text":"Audit express offert (1 jour)","included":true}],"featured":true},{"name":"Partenaire Premium","price":"750 000","period":"FCFA / an","desc":"Pour les grandes entreprises et partenaires institutionnels.","features":[{"text":"Membres illimités","included":true},{"text":"Tous les avantages organisation","included":true},{"text":"RSSI à la demande (10h/mois)","included":true},{"text":"Support sécurité prioritaire 24/7","included":true},{"text":"Tableaux de bord de risques","included":true},{"text":"Co-organisation d''événements","included":true}],"featured":false}]');
