INSERT OR IGNORE INTO content_sections (name, data) VALUES ('values', '[{"icon":"Target","title":"Notre mission","text":"Promouvoir les bonnes pratiques de sécurité de l''information au Congo, fédérer les professionnels du secteur et accompagner les organisations dans leur transformation numérique sécurisée."},{"icon":"Eye","title":"Notre vision","text":"Faire du Congo un pôle de référence en cybersécurité en Afrique centrale, grâce à une communauté d''experts engagés et des entreprises résilientes face aux cybermenaces."},{"icon":"HeartHandshake","title":"Nos valeurs","text":"Excellence, intégrité, partage de connaissances et éthique professionnelle guident chacune de nos actions, de nos formations et de nos missions d''accompagnement."}]');
INSERT OR IGNORE INTO content_sections (name, data) VALUES ('trainings', '[{"icon":"ShieldCheck","title":"Fondamentaux de la cybersécurité","text":"Initiation aux concepts essentiels : menaces, vulnérabilités, contrôles et bonnes pratiques de protection des systèmes d''information."},{"icon":"Lock","title":"ISO 27001 & gestion des risques","text":"Mettre en place un SMSI conforme à l''ISO 27001 et piloter l''analyse des risques de sécurité de l''information."},{"icon":"Bug","title":"Test d''intrusion & sécurité offensive","text":"Méthodologies de pentest, découverte de vulnérabilités applicatives et techniques de remédiation."},{"icon":"Network","title":"Sécurité réseau & cloud","text":"Sécurisation des infrastructures, segmentation, durcissement et bonnes pratiques cloud (DevSecOps)."},{"icon":"FileSearch","title":"Conformité RGPD / NIS2","text":"Comprendre les exigences légales applicables au Congo et en Afrique centrale, et les intégrer à vos projets."},{"icon":"CloudCog","title":"Réponse aux incidents & SOC","text":"Mettre en place un SOC, détecter, analyser et répondre efficacement aux incidents de sécurité."}]');
INSERT OR IGNORE INTO content_sections (name, data) VALUES ('commissions', '[{"id":"formations-certifications","icon":"GraduationCap","title":"Commission Formations et certifications","text":"Programmes de montée en compétence, ateliers pratiques et accompagnement vers les certifications professionnelles reconnues en sécurité de l''information."},{"id":"veille-recherches","icon":"Search","title":"Commission Veille et Recherches","text":"Surveillance des vulnérabilités émergentes, partage d''outils, retours d''expérience entre experts et publication de travaux de recherche."},{"id":"plaidoyer-institutionnel","icon":"Handshake","title":"Commission Plaidoyer et relations institutionnelles","text":"Dialogue avec les institutions publiques et privées pour structurer la cybersécurité au niveau national et faire évoluer le cadre réglementaire."},{"id":"innovation-projets","icon":"Lightbulb","title":"Commission Innovation et projets","text":"Conception et pilotage des projets innovants de l''association, des solutions concrètes au service de la sécurité numérique congolaise."},{"id":"contentieux-conformite","icon":"Scale","title":"Commission Contentieux et Conformité","text":"Veille sur les cadres réglementaires (ANSSI, ISO 27001, NIS2, RGPD) et accompagnement des organisations congolaises vers la conformité."},{"id":"communication-medias","icon":"Megaphone","title":"Commission Communication et Médias","text":"Campagnes de sensibilisation, présence médiatique et animation des réseaux de l''association pour informer le public sur les risques numériques."}]');
INSERT OR IGNORE INTO content_sections (name, data) VALUES ('events', '[{"icon":"Users","title":"Rencontres mensuelles","date":"Chaque 1er jeudi du mois","place":"Brazzaville","text":"Rencontres d''échange entre professionnels de la sécurité de l''information, partage de retours d''expérience et veille collective."},{"icon":"Trophy","title":"Capture The Flag (CTF)","date":"Deux fois par an","place":"En ligne","text":"Compétitions pratiques de cybersécurité ouvertes aux étudiants et aux professionnels pour développer leurs compétences techniques."},{"icon":"CalendarDays","title":"Conférence annuelle APSI-CG","date":"Chaque année","place":"Brazzaville","text":"Le rendez-vous de la cybersécurité au Congo : conférences, panels et ateliers avec des experts nationaux et internationaux."},{"icon":"MapPin","title":"Ateliers de sensibilisation","date":"Tout au long de l''année","place":"Entreprises & écoles","text":"Campagnes de sensibilisation aux risques numériques destinées aux organisations, aux écoles et au grand public."}]');
INSERT OR IGNORE INTO content_sections (name, data) VALUES ('contact_cards', '[{"icon":"Mail","title":"Écrivez-nous","lines":["contact@apsi-cg.org"],"href":"mailto:contact@apsi-cg.org"},{"icon":"Phone","title":"Appelez-nous","lines":["+242 06 123 45 67","+242 05 123 45 67"],"href":"tel:+242061234567"},{"icon":"MapPin","title":"Notre adresse","lines":["Avenue Amílcar Cabral, Centre-ville","Brazzaville, République du Congo"]},{"icon":"Clock","title":"Horaires","lines":["Lun – Ven : 8h00 – 17h30","Réponse incidents : 24/7"]}]');
INSERT OR IGNORE INTO blog_posts (title, slug, date, category, excerpt, image, body, published) VALUES ('Ransomware : 7 réflexes essentiels pour protéger votre entreprise', 'ransomware-7-reflexes-essentiels-pour-proteger-votre-entreprise', '12 Juillet 2026', 'Cybersécurité', 'Les attaques par rançongiciel explosent en Afrique centrale. Découvrez les bonnes pratiques pour réduire votre exposition et réagir efficacement.', 'https://images.unsplash.com/photo-1550751827-4bd374c3f58b?auto=format&fit=crop&w=900&q=80', '', 1);
INSERT OR IGNORE INTO blog_posts (title, slug, date, category, excerpt, image, body, published) VALUES ('NIS2 et entreprises congolaises : ce qui change pour vous', 'nis2-et-entreprises-congolaises-ce-qui-change-pour-vous', '28 Juin 2026', 'Réglementation', 'La directive NIS2 étend son champ d''application. Comprenez les obligations qui s''appliquent à votre secteur et comment vous y préparer.', 'https://images.unsplash.com/photo-1563013544-824ae1b704d3?auto=format&fit=crop&w=900&q=80', '', 1);
INSERT OR IGNORE INTO blog_posts (title, slug, date, category, excerpt, image, body, published) VALUES ('Sensibilisation : comment la data aide vos équipes à se protéger', 'sensibilisation-comment-la-data-aide-vos-equipes-a-se-proteger', '05 Juin 2026', 'Formation', 'Les statistiques de phishing simulé révèlent vos points faibles humains. Comment transformer ces données en programme de formation efficace.', 'https://images.unsplash.com/photo-1562813733-b31f71025d54?auto=format&fit=crop&w=900&q=80', '', 1);
INSERT OR IGNORE INTO trainings (slug, icon, title, category, level, format, duration, next_session, description, active, sort_order) VALUES ('fondamentaux-cybersecurite', 'ShieldCheck', 'Fondamentaux de la cybersécurité', 'Sensibilisation', 'Débutant', 'Présentiel', '2 jours', 'Session mensuelle', 'Comprendre les menaces, vulnérabilités, contrôles de base et bonnes pratiques de protection des systèmes d''information.', 1, 1);
INSERT OR IGNORE INTO trainings (slug, icon, title, category, level, format, duration, next_session, description, active, sort_order) VALUES ('iso-27001-lead-implementer', 'Lock', 'ISO 27001 Lead Implementer', 'Gouvernance', 'Avancé', 'Hybride', '5 jours', 'Sur inscription', 'Structurer un SMSI, conduire l''analyse de risques, produire les livrables clés et préparer l''organisation à la certification.', 1, 2);
INSERT OR IGNORE INTO trainings (slug, icon, title, category, level, format, duration, next_session, description, active, sort_order) VALUES ('audit-securite-si', 'FileSearch', 'Audit de sécurité SI', 'Audit', 'Intermédiaire', 'Présentiel', '3 jours', 'Trimestrielle', 'Préparer une mission d''audit, collecter les preuves, qualifier les écarts et restituer un rapport exploitable par la direction.', 1, 3);
INSERT OR IGNORE INTO trainings (slug, icon, title, category, level, format, duration, next_session, description, active, sort_order) VALUES ('test-intrusion-web', 'Bug', 'Test d''intrusion web', 'Technique', 'Avancé', 'Atelier', '4 jours', 'Sur inscription', 'Méthodologie de pentest applicatif, OWASP Top 10, exploitation contrôlée, priorisation des vulnérabilités et remédiation.', 1, 4);
INSERT OR IGNORE INTO trainings (slug, icon, title, category, level, format, duration, next_session, description, active, sort_order) VALUES ('securite-reseau-entreprise', 'Network', 'Sécurité réseau d''entreprise', 'Technique', 'Intermédiaire', 'Présentiel', '3 jours', 'Bimestrielle', 'Segmentation, pare-feu, durcissement, supervision, VPN et contrôle des accès sur les architectures réseau critiques.', 1, 5);
INSERT OR IGNORE INTO trainings (slug, icon, title, category, level, format, duration, next_session, description, active, sort_order) VALUES ('securite-cloud-devsecops', 'CloudCog', 'Sécurité cloud & DevSecOps', 'Cloud', 'Intermédiaire', 'Hybride', '3 jours', 'Sur inscription', 'Sécuriser les environnements cloud, les pipelines CI/CD, les conteneurs, les secrets et les déploiements applicatifs.', 1, 6);
INSERT OR IGNORE INTO trainings (slug, icon, title, category, level, format, duration, next_session, description, active, sort_order) VALUES ('reponse-incidents-gestion-crise', 'Siren', 'Réponse aux incidents & gestion de crise', 'SOC & Incident', 'Intermédiaire', 'Atelier', '2 jours', 'Mensuelle', 'Préparer les procédures, qualifier un incident, coordonner les équipes, communiquer en crise et capitaliser après l''événement.', 1, 7);
INSERT OR IGNORE INTO trainings (slug, icon, title, category, level, format, duration, next_session, description, active, sort_order) VALUES ('soc-analyst-niveau-1', 'Laptop', 'SOC analyst niveau 1', 'SOC & Incident', 'Débutant', 'Atelier', '4 jours', 'Sur inscription', 'Lire les alertes, enrichir les événements, appliquer les playbooks, escalader les cas et suivre les indicateurs opérationnels.', 1, 8);
